const runStep = (step: Step): Result => {
  if (step.op === "quote") return { premium: quotePremium(step.items) };
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): { results: Result[] } => {
  return { results: scenario.steps.map(runStep) };
};
